import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # Parse the four integers
    a = [int(x) for x in input_data[:4]]

    # Count the frequency of each color
    counts = {}
    for color in a:
        if color in counts:
            counts[color] += 1
        else:
            counts[color] = 1

    # Calculate the maximum number of operations
    # Each operation requires two balls of the same color.
    # So we take floor(count / 2) for each color and sum them up.
    max_operations = 0
    for count in counts.values():
        max_operations += count // 2

    print(max_operations)

if __name__ == "__main__":
    solve()

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Identify all indices where a strictly increasing subarray of length k starts
        # A subarray starting at i is strictly increasing if for all j in [0, k-1]:
        # nums[i+j] < nums[i+j+1] (for j from 0 to k-2)

        start_indices = []

        # Check each possible starting position
        for i in range(n - k + 1):
            is_increasing = True
            for j in range(k - 1):
                if nums[i + j + 1] <= nums[i + j]:
                    is_increasing = False
                    break
            if is_increasing:
                start_indices.append(i)

        # We need two adjacent subarrays, meaning if one starts at 'a', the other must start at 'a + k'
        # So we check if there exists any index i such that both i and i + k are in start_indices

        for i in start_indices:
            if (i + k) in start_indices:
                return True

        return False

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = 0

        # Since the constraints are small (nums.length <= 100 and nums[i] <= 10),
        # we can iterate over all possible subarrays and check the condition.
        # Time complexity will be O(n^2 * log(max_val)), which is well within limits.

        for i in range(n):
            current_gcd = nums[i]
            current_lcm = nums[i]
            current_prod = nums[i]

            for j in range(i, n):
                num = nums[j]

                # Update GCD of the subarray [i..j]
                current_gcd = gcd(current_gcd, num)

                # Update LCM of the subarray [i..j]
                current_lcm = lcm(current_lcm, num)

                # Update product of the subarray [i..j]
                current_prod *= num

                # Check if the subarray is product equivalent
                if current_prod == current_gcd * current_lcm:
                    max_len = max(max_len, j - i + 1)

        return max_len

    # Helper functions for GCD and LCM
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)
